namespace InventoryApp.Services;

public record EquipmentItem(int Id, string Name, string Location, DateTime LastInspected);

public class EquipmentService
{
    public async Task<List<EquipmentItem>> GetEquipmentAsync()
    {
        // Simulate a slow data source
        await Task.Delay(500);

        return new List<EquipmentItem>
        {
            new(1, "Forklift A",        "Warehouse 1",  new DateTime(2026, 5, 10)),
            new(2, "Conveyor Belt B",    "Warehouse 2",  new DateTime(2026, 4, 22)),
            new(3, "Pallet Jack C",      "Loading Dock",  new DateTime(2026, 3, 15)),
            new(4, "Crane D",            "Yard",          new DateTime(2026, 5, 30)),
            new(5, "Compressor E",       "Maintenance",   new DateTime(2026, 1, 8)),
            new(6, "Welding Rig F",      "Shop Floor",    new DateTime(2025, 12, 19)),
            new(7, "Hydraulic Press G",  "Shop Floor",    new DateTime(2026, 2, 14)),
        };
    }
}

@page "/inventory"
@rendermode InteractiveServer
@attribute [StreamRendering]
@using InventoryApp.Services
@inject EquipmentService EquipmentSvc
@inject PersistentComponentState PersistentState
@implements IDisposable

<PageTitle>Inventory</PageTitle>
<h1>Equipment Inventory</h1>

@if (items is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in items)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToShortDateString()</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<EquipmentItem>? items;
    private PersistingComponentStateSubscription persistingSubscription;

    protected override async Task OnInitializedAsync()
    {
        // Subscribe to persist the data into the HTML before the prerender completes.
        persistingSubscription = PersistentState.RegisterOnPersisting(PersistItems);

        // If data was already persisted during prerender, reuse it instead of fetching again.
        if (PersistentState.TryTakeFromJson<List<EquipmentItem>>("inventory", out var restored))
        {
            items = restored;
        }
        else
        {
            items = await EquipmentSvc.GetEquipmentAsync();
        }
    }

    private Task PersistItems()
    {
        PersistentState.PersistAsJson("inventory", items);
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        persistingSubscription.Dispose();
    }
}

